import * as React from 'react'
import { Search, MessageSquare, Pin, Pencil, Archive, Trash2, Plus, Check, X } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { useControllableState } from '@/components/ui/util'
import { useAsyncAction } from '@/components/ui/product-utils'
import { cn } from '@/lib/utils'
export interface ConversationHistoryItem {
  id: string
  title: string
  updatedAt: string
  group?: string
  pinned?: boolean
  archived?: boolean
  description?: string
}
export type ConversationHistoryAction =
  { kind: 'rename'; title: string } | { kind: 'archive' | 'restore' | 'delete' | 'pin' | 'unpin' }
export interface ConversationHistoryProps extends Omit<React.ComponentProps<'nav'>, 'onSelect'> {
  /** Controlled items. Publish successful persistence results through this prop. */
  items: ConversationHistoryItem[]
  selectedId?: string
  onSelect: (item: ConversationHistoryItem) => void
  onNew?: () => void
  onItemsChange?: (items: ConversationHistoryItem[]) => void
  /** Persist an action and update items, or use onItemsChange to publish the next list. */
  onAction?: (
    item: ConversationHistoryItem,
    action: ConversationHistoryAction,
    options: { signal: AbortSignal },
  ) => void | Promise<void>
  hasMore?: boolean
  onLoadMore?: (options: { signal: AbortSignal }) => void | Promise<void>
  loading?: boolean
  disabled?: boolean
  label?: string
}
/** A data-driven conversation navigator with injected persistence and pagination. */
export function ConversationHistory({
  items,
  selectedId,
  onSelect,
  onNew,
  onItemsChange,
  onAction,
  hasMore = false,
  onLoadMore,
  loading = false,
  disabled = false,
  label = 'Conversation history',
  className,
  ...props
}: ConversationHistoryProps) {
  const [query, setQuery] = React.useState(''),
    [archived, setArchived] = React.useState(false),
    [editing, setEditing] = React.useState<string | null>(null),
    [draft, setDraft] = React.useState(''),
    action = useAsyncAction(),
    [source, setSource] = useControllableState({
      value: items,
      defaultValue: [],
      onChange: onItemsChange,
    })
  const matches = source
      .filter(
        (item) =>
          !!item.archived === archived &&
          `${item.title} ${item.description ?? ''}`.toLowerCase().includes(query.toLowerCase()),
      )
      .sort(
        (a, b) =>
          Number(!!b.pinned) - Number(!!a.pinned) ||
          Date.parse(b.updatedAt) - Date.parse(a.updatedAt),
      ),
    groups = [
      ...new Set(
        matches.map((item) =>
          item.pinned ? 'Pinned' : (item.group ?? new Date(item.updatedAt).toLocaleDateString()),
        ),
      ),
    ]
  const change = (item: ConversationHistoryItem, next: ConversationHistoryAction) => {
    if (disabled || action.busy || (!onAction && !onItemsChange)) return
    void action.run(async (signal) => {
      await onAction?.(item, next, { signal })
      if (signal.aborted) return
      setSource((previous) =>
        next.kind === 'delete'
          ? previous.filter((entry) => entry.id !== item.id)
          : previous.map((entry) =>
              entry.id !== item.id
                ? entry
                : next.kind === 'rename'
                  ? { ...entry, title: next.title }
                  : next.kind === 'archive' || next.kind === 'restore'
                    ? { ...entry, archived: next.kind === 'archive' }
                    : { ...entry, pinned: next.kind === 'pin' },
            ),
      )
      setEditing(null)
    })
  }
  const valid =
      source.every(
        (item) => item.id && item.title && Number.isFinite(Date.parse(item.updatedAt)),
      ) && new Set(source.map((item) => item.id)).size === source.length,
    mutable = !!onAction || !!onItemsChange
  return (
    <nav
      {...props}
      data-slot="conversation-history"
      aria-label={label}
      className={cn('w-full min-w-0 space-y-3 rounded-xl border bg-background p-3', className)}
    >
      <div className="flex items-center gap-2">
        <h3 className="min-w-0 flex-1 text-sm font-semibold">{label}</h3>
        {onNew && (
          <Button
            type="button"
            variant="outline"
            size="icon-sm"
            aria-label="New conversation"
            disabled={disabled}
            onClick={onNew}
          >
            <Plus />
          </Button>
        )}
      </div>
      <div className="relative">
        <Search className="pointer-events-none absolute start-3 top-2.5 size-4 text-muted-foreground" />
        <Input
          aria-label="Search conversations"
          placeholder="Search conversations…"
          className="ps-9"
          value={query}
          onValueChange={setQuery}
        />
      </div>
      <div className="flex gap-1" role="group" aria-label="History filter">
        {['Active', 'Archived'].map((filter, index) => (
          <Button
            key={filter}
            type="button"
            variant={archived === !!index ? 'secondary' : 'ghost'}
            size="xs"
            onClick={() => setArchived(!!index)}
            aria-pressed={archived === !!index}
          >
            {filter}
          </Button>
        ))}
      </div>
      {!valid ? (
        <p role="alert" className="text-xs text-destructive">
          Conversations need unique IDs, titles and valid dates.
        </p>
      ) : (
        <div className="max-h-[30rem] space-y-4 overflow-auto">
          {groups.map((group) => (
            <section key={group} aria-label={group}>
              <h4 className="mb-1 px-2 text-[10px] font-medium text-muted-foreground">{group}</h4>
              <ul className="space-y-1">
                {matches
                  .filter(
                    (item) =>
                      (item.pinned
                        ? 'Pinned'
                        : (item.group ?? new Date(item.updatedAt).toLocaleDateString())) === group,
                  )
                  .map((item) => (
                    <li
                      key={item.id}
                      className={cn(
                        'group rounded-lg border border-transparent',
                        selectedId === item.id && 'border-border bg-accent',
                      )}
                    >
                      {editing === item.id ? (
                        <form
                          className="flex items-center gap-1 p-2"
                          onSubmit={(event) => {
                            event.preventDefault()
                            if (draft.trim()) change(item, { kind: 'rename', title: draft.trim() })
                          }}
                        >
                          <Input
                            aria-label="Conversation title"
                            value={draft}
                            autoFocus
                            onValueChange={setDraft}
                            disabled={action.busy}
                          />
                          <Button
                            type="submit"
                            variant="ghost"
                            size="icon-xs"
                            aria-label="Save conversation title"
                            disabled={!draft.trim() || action.busy}
                          >
                            <Check />
                          </Button>
                          <Button
                            type="button"
                            variant="ghost"
                            size="icon-xs"
                            aria-label="Cancel rename"
                            disabled={action.busy}
                            onClick={() => setEditing(null)}
                          >
                            <X />
                          </Button>
                        </form>
                      ) : (
                        <>
                          <button
                            type="button"
                            disabled={disabled}
                            onClick={() => onSelect(item)}
                            aria-current={selectedId === item.id ? 'page' : undefined}
                            className="flex w-full items-center gap-2 rounded-lg px-2 py-2 text-start outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring"
                          >
                            <MessageSquare className="size-3.5 shrink-0 text-muted-foreground" />
                            <span className="min-w-0 flex-1 truncate text-xs">{item.title}</span>
                            {item.pinned && <Pin className="size-3 text-muted-foreground" />}
                          </button>
                          {mutable && (
                            <div className="flex items-center gap-1 px-2 pb-1">
                              {(
                                [
                                  {
                                    kind: item.pinned ? 'unpin' : 'pin',
                                    label: item.pinned ? 'Unpin' : 'Pin',
                                    Icon: Pin,
                                  },
                                  { kind: 'rename', label: 'Rename', Icon: Pencil },
                                  {
                                    kind: item.archived ? 'restore' : 'archive',
                                    label: item.archived ? 'Restore' : 'Archive',
                                    Icon: Archive,
                                  },
                                  { kind: 'delete', label: 'Delete', Icon: Trash2 },
                                ] as const
                              ).map(({ kind, label: actionLabel, Icon }) => (
                                <Button
                                  key={kind}
                                  type="button"
                                  variant="ghost"
                                  size="icon-xs"
                                  aria-label={`${actionLabel} ${item.title}`}
                                  disabled={disabled || action.busy}
                                  onClick={() => {
                                    if (kind === 'rename') {
                                      setDraft(item.title)
                                      setEditing(item.id)
                                    } else change(item, { kind })
                                  }}
                                >
                                  <Icon />
                                </Button>
                              ))}
                            </div>
                          )}
                        </>
                      )}
                    </li>
                  ))}
              </ul>
            </section>
          ))}
          {!matches.length && (
            <p role="status" className="p-5 text-center text-xs text-muted-foreground">
              No conversations found.
            </p>
          )}
        </div>
      )}
      {hasMore && (
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="w-full"
          disabled={disabled || loading || action.busy || !onLoadMore}
          onClick={() => void action.run((signal) => onLoadMore?.({ signal }))}
        >
          {loading || action.busy ? 'Loading…' : 'Load more conversations'}
        </Button>
      )}
      {action.error && (
        <p role="alert" className="text-xs text-destructive">
          {action.error}
        </p>
      )}
    </nav>
  )
}

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import { Slot } from 'radix-ui'
import { Loader2 } from 'lucide-react'

const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground hover:bg-primary/90',
        destructive:
          'bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40',
        outline:
          'border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50',
        secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
        link: 'text-primary underline-offset-4 hover:underline',
        soft: 'bg-primary/10 text-primary hover:bg-primary/15',
        success: 'bg-emerald-600 text-white hover:bg-emerald-700',
        warning: 'bg-amber-400 text-amber-950 hover:bg-amber-500',
        dashed:
          'border border-dashed bg-background text-foreground hover:border-primary hover:text-primary',
      },
      size: {
        default:
          'h-[var(--ergon-control-height,2.25rem)] px-4 py-[var(--ergon-control-py,0.5rem)] has-[>svg]:px-3',
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: 'h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5',
        lg: 'h-10 rounded-md px-6 has-[>svg]:px-4',
        icon: 'size-9',
        'icon-xs': "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        'icon-sm': 'size-8',
        'icon-lg': 'size-10',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

/**
 * Composes button variants, loading state, and optional slot rendering. Compact-density styles travel with the installed source.
 */
function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }) {
  const Comp = asChild ? Slot.Root : 'button'

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size }), className)}
      aria-busy={loading || undefined}
      {...props}
      disabled={props.disabled || loading}
    >
      {asChild ? (
        children
      ) : (
        <>
          {loading && <Loader2 className="animate-spin" />}
          {children}
        </>
      )}
    </Comp>
  )
}

export { Button, buttonVariants }

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import * as React from 'react'
import { Eye, EyeOff, X } from 'lucide-react'
import { cn } from '@/lib/utils'
import { useControllableState } from '@/components/ui/util'
export interface InputProps extends Omit<React.ComponentProps<'input'>, 'prefix'> {
  leading?: React.ReactNode
  trailing?: React.ReactNode
  allowClear?: boolean
  showCount?: boolean
  passwordToggle?: boolean
  onValueChange?: (value: string) => void
}
/**
 * Renders an input with optional leading content, clear action, and password visibility controls, including portable compact-density styling.
 */
export function Input({
  className,
  type = 'text',
  value,
  defaultValue = '',
  onChange,
  onValueChange,
  leading,
  trailing,
  allowClear,
  showCount,
  passwordToggle,
  ref,
  ...props
}: InputProps) {
  const [current, setCurrent] = useControllableState<string>({
    value: value === undefined ? undefined : String(value),
    defaultValue: String(defaultValue),
    onChange: onValueChange,
  })
  const [reveal, setReveal] = React.useState(false),
    input = React.useRef<HTMLInputElement>(null)
  React.useImperativeHandle(ref, () => input.current!)
  const field = (
    <input
      {...props}
      ref={input}
      type={passwordToggle && reveal ? 'text' : type}
      data-slot="input"
      value={current}
      onChange={(event) => {
        setCurrent(event.target.value)
        onChange?.(event)
      }}
      className={cn(
        'h-[var(--ergon-control-height,2.25rem)] w-full min-w-0 rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-xs outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50 focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/30 aria-invalid:border-destructive',
        leading && 'pl-9',
        (trailing || allowClear || passwordToggle) && 'pr-10',
        className,
      )}
    />
  )
  if (!leading && !trailing && !allowClear && !showCount && !passwordToggle) return field
  return (
    <span className="relative inline-flex w-full flex-col">
      <span className="relative flex w-full items-center">
        {leading && <span className="absolute left-3 z-1 text-muted-foreground">{leading}</span>}
        {field}
        <span className="absolute right-2 flex items-center gap-1 text-muted-foreground">
          {allowClear && current && !props.disabled && !props.readOnly && (
            <button
              type="button"
              aria-label="Clear input"
              onClick={() => {
                const element = input.current
                if (!element) return
                Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value')?.set?.call(
                  element,
                  '',
                )
                element.dispatchEvent(new Event('input', { bubbles: true }))
                setCurrent('')
                element.focus()
              }}
            >
              <X size={14} />
            </button>
          )}
          {passwordToggle && (
            <button
              type="button"
              aria-label={reveal ? 'Hide password' : 'Show password'}
              onClick={() => setReveal((v) => !v)}
            >
              {reveal ? <EyeOff size={15} /> : <Eye size={15} />}
            </button>
          )}
          {trailing}
        </span>
      </span>
      {showCount && (
        <span className="mt-1 self-end text-[10px] text-muted-foreground">
          {current.length}
          {props.maxLength ? ` / ${props.maxLength}` : ''}
        </span>
      )}
    </span>
  )
}
export function OTPInput({
  value,
  defaultValue = '',
  onValueChange,
  length = 6,
  disabled,
  pattern = /\d/,
}: {
  value?: string
  defaultValue?: string
  onValueChange?: (code: string) => void
  length?: number
  disabled?: boolean
  pattern?: RegExp
}) {
  const [code, setCode] = useControllableState({ value, defaultValue, onChange: onValueChange })
  const refs = React.useRef<(HTMLInputElement | null)[]>([])
  const clean = (text: string) =>
    Array.from(text)
      .filter((char) => {
        pattern.lastIndex = 0
        return pattern.test(char)
      })
      .join('')
      .slice(0, length)
  return (
    <div
      role="group"
      aria-label="One-time code"
      className="flex gap-2"
      onPaste={(e) => {
        e.preventDefault()
        const text = clean(e.clipboardData.getData('text'))
        setCode(text)
        refs.current[Math.min(text.length, length - 1)]?.focus()
      }}
    >
      {Array.from({ length }, (_, index) => (
        <input
          key={index}
          ref={(el) => {
            refs.current[index] = el
          }}
          aria-label={`Code digit ${index + 1}`}
          inputMode="numeric"
          autoComplete={index === 0 ? 'one-time-code' : 'off'}
          value={code[index] ?? ''}
          disabled={disabled}
          maxLength={1}
          className="h-11 w-9 rounded-lg border bg-background text-center font-mono text-lg outline-ring"
          onChange={(e) => {
            const char = clean(e.target.value).slice(-1)
            setCode((code.slice(0, index) + char + code.slice(index + 1)).slice(0, length))
            if (char) refs.current[Math.min(index + 1, length - 1)]?.focus()
          }}
          onKeyDown={(e) => {
            if (e.key === 'Backspace') {
              if (!code[index]) refs.current[Math.max(0, index - 1)]?.focus()
              else setCode(code.slice(0, index) + code.slice(index + 1))
            }
            if (e.key === 'ArrowLeft') refs.current[Math.max(0, index - 1)]?.focus()
            if (e.key === 'ArrowRight') refs.current[Math.min(length - 1, index + 1)]?.focus()
          }}
        />
      ))}
    </div>
  )
}

import * as React from 'react'
import { breakpoints, type Breakpoint } from '@/lib/responsive'
export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}) {
  const [internal, setInternal] = React.useState(defaultValue)
  const current = value === undefined ? internal : value
  const currentRef = React.useRef(current),
    valueRef = React.useRef(value),
    changeRef = React.useRef(onChange)
  currentRef.current = current
  valueRef.current = value
  changeRef.current = onChange
  const set = React.useCallback((next: T | ((previous: T) => T)) => {
    const previous = currentRef.current
    const result = typeof next === 'function' ? (next as (previous: T) => T)(previous) : next
    if (Object.is(previous, result)) return
    currentRef.current = result
    if (valueRef.current === undefined) setInternal(result)
    changeRef.current?.(result)
  }, [])
  return [current, set] as const
}
export function useMediaQuery(query: string) {
  const [matches, setMatches] = React.useState(
    () => typeof window !== 'undefined' && window.matchMedia(query).matches,
  )
  React.useEffect(() => {
    const m = window.matchMedia(query)
    const update = () => setMatches(m.matches)
    update()
    m.addEventListener('change', update)
    return () => m.removeEventListener('change', update)
  }, [query])
  return matches
}
export function useDebouncedValue<T>(value: T, delay = 250) {
  const [debounced, set] = React.useState(value)
  React.useEffect(() => {
    const id = setTimeout(() => set(value), delay)
    return () => clearTimeout(id)
  }, [value, delay])
  return debounced
}
export async function copyToClipboard(text: string) {
  await navigator.clipboard.writeText(text)
}
export function useBreakpoints() {
  const [width, setWidth] = React.useState(() =>
    typeof window === 'undefined' ? 0 : window.innerWidth,
  )
  React.useEffect(() => {
    const update = () => setWidth(window.innerWidth)
    window.addEventListener('resize', update)
    return () => window.removeEventListener('resize', update)
  }, [])
  return Object.fromEntries(
    Object.entries(breakpoints).map(([key, min]) => [key, width >= min]),
  ) as Record<Breakpoint, boolean>
}

import type { CSSProperties } from 'react'
export const breakpoints = { xs: 0, sm: 640, md: 768, lg: 1024, xl: 1280, '2xl': 1536 } as const
export type Breakpoint = keyof typeof breakpoints
export type Responsive<T> = T | Partial<Record<Breakpoint, T>>
export function responsiveStyle<T>(value: Responsive<T> | undefined, name: string): CSSProperties {
  if (value === undefined) return {}
  const values = typeof value === 'object' && value !== null ? value : { xs: value }
  return Object.fromEntries(
    Object.entries(values).map(([key, v]) => [`--${name}-${key}`, v]),
  ) as CSSProperties
}
export const responsiveCSS = Object.entries(breakpoints)
  .map(([, min], index) => {
    const fallback = (name: string, initial: string) =>
      Object.keys(breakpoints)
        .slice(0, index + 1)
        .reduce((result, key) => `var(--${name}-${key},${result})`, initial)
    return `@media(min-width:${min}px){.ergon-col{width:calc(${fallback('span', '24')} / 24 * 100%);margin-inline-start:calc(${fallback('offset', '0')} / 24 * 100%);order:${fallback('order', '0')}}.ergon-flex{gap:${fallback('gap', '12px')};flex-direction:${fallback('direction', 'row')}}}`
  })
  .join('')

import * as React from 'react'
import { useControllableState } from '@/components/ui/util'

/** Runs the latest cancellable action without publishing stale results after unmount. */
export function useAsyncAction() {
  const active = React.useRef<AbortController | null>(null)
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState('')
  React.useEffect(
    () => () => {
      active.current?.abort()
      active.current = null
    },
    [],
  )
  const cancel = React.useCallback(() => {
    active.current?.abort()
    active.current = null
    setBusy(false)
  }, [])
  const run = React.useCallback(async <T>(task: (signal: AbortSignal) => T | Promise<T>) => {
    active.current?.abort()
    const controller = new AbortController()
    active.current = controller
    setBusy(true)
    setError('')
    try {
      const value = await task(controller.signal)
      if (!controller.signal.aborted && active.current === controller) return value
    } catch (failure) {
      if (!controller.signal.aborted && active.current === controller)
        setError(failure instanceof Error ? failure.message : 'The action failed.')
    } finally {
      if (active.current === controller) {
        active.current = null
        setBusy(false)
      }
    }
    return undefined
  }, [])
  return { busy, error, run, cancel, clearError: () => setError('') }
}

/** Bounded immutable history for controlled or uncontrolled editors. */
export function useEditorHistory<T>({
  value,
  defaultValue,
  onChange,
  limit = 50,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
  limit?: number
}) {
  const [current, setCurrent] = useControllableState({ value, defaultValue, onChange })
  const [past, setPast] = React.useState<T[]>([])
  const [future, setFuture] = React.useState<T[]>([])
  const expected = React.useRef(current)
  React.useEffect(() => {
    if (value !== undefined && value !== expected.current) {
      expected.current = value
      setPast([])
      setFuture([])
    }
  }, [value])
  const apply = (next: T) => {
    expected.current = next
    setCurrent(next)
  }
  return {
    value: current,
    canUndo: past.length > 0,
    canRedo: future.length > 0,
    commit(next: T) {
      if (Object.is(next, current)) return
      setPast((previous) => [...previous, current].slice(-Math.max(1, Math.min(100, limit))))
      setFuture([])
      apply(next)
    },
    undo() {
      if (!past.length) return
      setPast(past.slice(0, -1))
      setFuture([current, ...future])
      apply(past[past.length - 1])
    },
    redo() {
      if (!future.length) return
      setPast([...past, current])
      setFuture(future.slice(1))
      apply(future[0])
    },
  }
}

/** Accepts explicit web/blob/image URLs and relative paths, never executable protocols. */
export function productURL(value: string, image = false): string | undefined {
  const clean = value.trim()
  if (
    !clean ||
    [...clean].some((character) => character.charCodeAt(0) <= 32 || character.charCodeAt(0) === 127)
  )
    return
  if (image && /^data:image\/(?:png|jpeg|webp|gif);base64,[\da-z+/=]+$/i.test(clean)) return clean
  try {
    const url = new URL(clean, 'https://ergon.invalid/')
    if (['http:', 'https:'].includes(url.protocol) || (image && url.protocol === 'blob:'))
      return clean
  } catch {
    /* Invalid input remains inert. */
  }
}
export const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, Number.isFinite(value) ? value : min))
/** Creates client-side entity IDs in secure and plain-HTTP browser contexts. */
export const productId = () => {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID()
  const bytes = globalThis.crypto.getRandomValues(new Uint8Array(16))
  bytes[6] = (bytes[6] & 15) | 64
  bytes[8] = (bytes[8] & 63) | 128
  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('')
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`
}
